import React, { useContext } from 'react';
import { GameClientContext } from '../contexts/GameClientContext';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';
import { useGameExit } from '../hooks/useGameExit';
import {
  AppPage,
  HeroTopRow,
  MetaPill,
  MetaRow,
  PageDescription,
  PageEyebrow,
  PageGrid,
  PageHeadingGroup,
  PageHero,
  PagePanel,
  PageShell,
  PageTitle,
  PanelActions,
  PanelDescription,
  PanelHeader,
  PanelTitle,
  PrimaryButton,
  SecondaryButton,
  SectionLabel,
  SupportingText
} from '../components/GameStyles';

const ModeGrid = styled(PageGrid)`
  grid-template-columns: repeat(12, minmax(0, 1fr));
`;

const ModeCard = styled(PagePanel)`
  grid-column: span 6;
  justify-content: space-between;
  min-height: 280px;

  @media (max-width: 900px) {
    grid-column: auto;
    min-height: auto;
  }
`;

const ModeList = styled.ul`
  margin: 0;
  padding-left: 1.1rem;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  color: var(--color-text-muted);
`;

const ModeSelection: React.FC = () => {
  const navigate = useNavigate();
  const { client } = useContext(GameClientContext);
  const playerName = client?.getPlayerName() || 'Player';

  const handleSingleMode = async() => {
    console.log("ModeSelection Player: ", client?.getPlayerName());
    if (!client) {
      return;
    }
    const roomID = await client.createRoom('1');
    await client.joinGame(roomID);
    navigate('/game/single', {
       state: { 
        mode: 'single' } });
  };

  const handleMultiMode = () => {
    console.log("ModeSelection Player: ", client?.getPlayerName());
    navigate('/rooms', {
       state: { 
        mode: 'multi' } });
  };

  useGameExit(client);

  return (
    <AppPage>
      <PageShell>
        <PageHero>
          <HeroTopRow>
            <PageEyebrow>Choose a mode</PageEyebrow>
            <MetaPill>{playerName}</MetaPill>
          </HeroTopRow>
          <PageHeadingGroup>
            <PageTitle>Decide how you want to play.</PageTitle>
            <PageDescription>
              Start a private practice round for yourself or move into the
              multiplayer room list to play with other people.
            </PageDescription>
          </PageHeadingGroup>
          <MetaRow>
            <MetaPill>Single-player practice</MetaPill>
            <MetaPill>Multiplayer rooms</MetaPill>
          </MetaRow>
        </PageHero>

        <ModeGrid>
          <ModeCard>
            <PanelHeader>
              <SectionLabel>Option 1</SectionLabel>
              <PanelTitle>Single-player</PanelTitle>
              <PanelDescription>
                Start playing immediately in a room created just for you.
              </PanelDescription>
            </PanelHeader>

            <ModeList>
              <li>Best for warm-ups and quick practice rounds.</li>
              <li>No need to wait for another player to join.</li>
              <li>Uses the same gameplay flow as the main game.</li>
            </ModeList>

            <PanelActions>
              <PrimaryButton onClick={handleSingleMode}>
                Start solo game
              </PrimaryButton>
            </PanelActions>
          </ModeCard>

          <ModeCard>
            <PanelHeader>
              <SectionLabel>Option 2</SectionLabel>
              <PanelTitle>Multiplayer</PanelTitle>
              <PanelDescription>
                Go to the room page to create a room or join one that already
                has open seats.
              </PanelDescription>
            </PanelHeader>

            <ModeList>
              <li>Browse open rooms before you commit to one.</li>
              <li>Create a room when you want to host the session.</li>
              <li>Join an existing room when you want to jump in faster.</li>
            </ModeList>

            <PanelActions>
              <SecondaryButton onClick={handleMultiMode}>
                Open room list
              </SecondaryButton>
            </PanelActions>
            <SupportingText>
              You&apos;ll choose between creating and joining on the next screen.
            </SupportingText>
          </ModeCard>
        </ModeGrid>
      </PageShell>
    </AppPage>
  );
};

export default ModeSelection;
